-- Warcraft Reborn Mystic Enchants whose proc event lived only in the tooltip: the event, spells and
-- conditions each proc effect fires on (spell_ascension_mystic_enchant_proc), reviewed against the tooltips.
DROP TABLE IF EXISTS `coa_mystic_enchant_proc`;
CREATE TABLE `coa_mystic_enchant_proc` (
  `enchant_spell` INT UNSIGNED NOT NULL,
  `effect` TINYINT UNSIGNED NOT NULL,
  `rule` TINYINT UNSIGNED NOT NULL COMMENT 'several rules may share an effect and event',
  `event` VARCHAR(24) NOT NULL,
  `school_mask` INT UNSIGNED NOT NULL DEFAULT 0,
  `spells` TEXT NOT NULL COMMENT 'every rank, space separated; empty = any spell',
  `chance` FLOAT NOT NULL DEFAULT 100,
  `cooldown_ms` INT UNSIGNED NOT NULL DEFAULT 0,
  `requires_aura` TEXT NOT NULL COMMENT 'the player has one of these (space separated)',
  `target_aura` TEXT NOT NULL COMMENT 'the target has one of these from the player',
  `conditions` TEXT NOT NULL COMMENT 'space separated, all must hold (see the script)',
  `consume_aura` TEXT NOT NULL COMMENT 'removed from the player when the effect procs',
  `comment` VARCHAR(255) NOT NULL DEFAULT '',
  PRIMARY KEY (`enchant_spell`, `effect`, `rule`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Mystic Enchant proc events (spell_ascension_mystic_enchant_proc)';

DELETE FROM `coa_mystic_enchant_proc`;

DROP TABLE IF EXISTS `coa_mystic_enchant_aura_link`;
CREATE TABLE `coa_mystic_enchant_aura_link` (
  `enchant_spell` INT UNSIGNED NOT NULL,
  `aura` TEXT NOT NULL COMMENT 'watched auras (every rank), space separated',
  `grant_spell` INT UNSIGNED NOT NULL,
  `comment` VARCHAR(255) NOT NULL DEFAULT '',
  PRIMARY KEY (`enchant_spell`, `grant_spell`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Mystic Enchant buffs granted while another aura lasts';
DELETE FROM `coa_mystic_enchant_aura_link`;

